mapper.select:
SELECT id, trace_id AS traceId, user_id AS userId, user_message AS userMessage, tool_name AS toolName, tool_desc AS toolDesc, tool_class AS toolClass, method_name AS methodName, arguments_json AS argumentsJson, result_text AS resultText, status, error_message AS errorMessage, duration_ms AS durationMs, create_time AS createTime FROM agent_tool_log WHERE 1 = 1
AND user_id = #{userId}
AND trace_id = #{traceId}
AND tool_name LIKE CONCAT('%', #{toolName}, '%')
AND status = #{status}
AND user_message LIKE CONCAT('%', #{userMessage}, '%')
ORDER BY id DESC
